export const isLuggage=p=>p?.type==='luggage'&&p.luggageProfile?.reviewed===true;
const ease=v=>{const t=Math.max(0,Math.min(1,v));return t*t*t*(t*(t*6-15)+10);};
export function luggageHold(profile,time,reduced=false,rest){const t=Number.isFinite(time)?Math.max(0,time):0,reach=reduced?1:ease(t/.8)*(1-ease((t-3.5)/.9)),turn=reduced?0:t<1?0:t<1.9?.24*ease((t-1)/.9):t<2.4?.24:t<3.3?.24*(1-ease((t-2.4)/.9)):0,k=.35,W=profile.widthCM*k,H=profile.heightCM*k,D=profile.depthCM*k,co=Math.cos(turn),si=Math.sin(turn),right={x:2,y:14+H,z:5},left={x:2-W/2*co+D/2*si,y:14+H*.88,z:5+W/2*si+D/2*co},hands=[left,right].map((b,i)=>{const a=rest?.[i]||{x:(i?1:-1)*8,y:24,z:2};return{x:a.x+(b.x-a.x)*reach,y:a.y+(b.y-a.y)*reach,z:a.z+(b.z-a.z)*reach};});return {reach,turn,hands,visible:reduced||reach>.02};}
export function luggageFactsHTML(p,esc){if(!isLuggage(p))return '';const a=p.luggageProfile;return `<section class="frame-facts luggage-facts"><h4>Earlier-generation Cabin reference</h4><p><strong>${a.heightCM} × ${a.widthCM} × ${a.depthCM} cm</strong> · height × width × depth, including wheels and handles. Published weight ${a.weightKG} kg and capacity ${a.capacityL} L.</p><p>${esc(p.sourceOfferNote)}</p><p>Cabin is the manufacturer’s format name. Airline acceptance, extended handle height, a measured physical fit and current stock are not established. This is not the newer 92653004 generation.</p><p>${esc(a.photoNote)}</p><p>Photo by ${esc(a.photoAuthor)}, <a href="${esc(a.photoLicenseUrl)}" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>. WebP encoding at original dimensions, without cropping or resizing. Original closed game geometry has no copied photo texture or brand artwork; hardware and interior details are adapted.</p></section>`;}
export function luggageNotebookHTML(st,esc){const p=st.products.find(isLuggage);if(!p)return '';const a=p.luggageProfile;return `<div class="modal-body luggage-notebook"><span class="eyebrow">CASE DIMENSIONS · FREE TO READ</span><h3>Read the format before choosing.</h3><div class="luggage-study-grid"><svg viewBox="0 0 300 270" role="img" aria-label="Original comparative case outlines showing overall dimensions"><rect x="25" y="25" width="140" height="192.5" rx="15" fill="#bbc2bf" stroke="#536961" stroke-width="3"/>${Array.from({length:7},(_,i)=>`<path d="M${40+i*18} 43V200" stroke="#dde0d7" stroke-width="4"/>`).join('')}<rect x="194" y="25" width="80.5" height="192.5" rx="12" fill="#82948c"/><path d="M62 25V16H128V25" stroke="#536961" fill="none" stroke-width="5"/><text x="95" y="245" text-anchor="middle">${a.widthCM} cm wide</text><text x="235" y="245" text-anchor="middle">${a.depthCM} cm deep</text></svg><div><h4>${esc(p.name)}</h4><p>${a.heightCM} cm high, ${a.widthCM} cm wide and ${a.depthCM} cm deep overall, including wheels and handles.</p><p>${a.weightKG} kg empty weight · ${a.capacityL} L capacity reference.</p><p>These original outlines compare proportions; they do not test an airline sizer or simulate packing capacity. Check applicable carrier requirements independently.</p><p>The earlier 92553004 model and the current 92653004 must not be treated as the same generation.</p></div></div><p>${esc(p.sourceOfferNote)}</p><button class="button secondary wide" data-action="detail" data-id="${esc(p.id)}">Inspect the case & source photograph</button><button class="button secondary wide" data-action="collection-open">Back to the collection desk</button></div>`;}
